class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n, m = len(nums), len(changeIndices)
        def ok(t):
            last = {}
            for s in range(t):
                last[changeIndices[s]] = s + 1
            if len(last) < n: return False
            free = 0
            for s in range(1, t + 1):
                i = changeIndices[s - 1]
                if last[i] == s:
                    if free < nums[i - 1]: return False
                    free -= nums[i - 1]
                else:
                    free += 1
            return True
        lo, hi, ans = 1, m, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if ok(mid): ans, hi = mid, mid - 1
            else: lo = mid + 1
        return ans

